              </legend>
              <p class="field-help" id="notification-help">Choose one notification method.</p>
              <div class="radio-list">
                ${optionMarkup}
              </div>
            </fieldset>
          </div>
          <button type="submit">Save preference</button>
        </form>
      `;
    }

    function App() {
      return `
        <main id="main-content">
          <section class="preference-card" aria-labelledby="page-title">
            <p class="eyebrow">Notification settings</p>
            <h1 id="page-title">Choose your preferred contact method</h1>
            <p class="intro">Tell us where you would like important updates to arrive.</p>
            ${NotificationPreferenceForm()}
          </section>
        </main>
      `;
    }

    document.getElementById("app").innerHTML = App();
  </script>
</body>
</html>
