   <script>
     const notificationOptions = [
       { id: "notification-email", value: "email", label: "Email" },
       { id: "notification-sms", value: "sms", label: "SMS" },
       { id: "notification-push", value: "push", label: "Push Notifications" }
     ];

     function RadioOption({ id, name, value, label }) {
       return `
         <div class="radio-option">
           <input id="${id}" type="radio" name="${name}" value="${value}" required>
           <label for="${id}">${label}</label>
         </div>
       `;
     }

     function NotificationPreferenceForm() {
       const optionMarkup = notificationOptions
         .map((option) => RadioOption({ ...option, name: "notificationPreference" }))
         .join("");

       return `
         <form action="#" method="post">
           <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>
           <div class="form-field">
             <fieldset aria-describedby="notification-help">
               <legend>
                 How do you prefer to receive notifications?
                 <span class="required-marker" aria-hidden="true">*</span>
               </legend>
               <p class="field-help" id="notification-help">Choose one notification method.</p>
               <div class="radio-list">
                 ${optionMarkup}
               </div>
             </fieldset>
           </div>
           <button type="submit">Save preference</button>
         </form>
       `;
     }

     function App() {
       return `
         <main id="main-content">
           <section class="preference-card" aria-labelledby="page-title">
             <p class="eyebrow">Notification settings</p>
             <h1 id="page-title">Choose your preferred contact method</h1>
             <p class="intro">Tell us where you would like important updates to arrive.</p>
             ${NotificationPreferenceForm()}
           </section>
         </main>
       `;
     }

     document.getElementById("app").innerHTML = App();
   </script>
 </body>
